db:select.db:sql:
SELECT lab_id, patient_external_id, patient_full_name, test_code, numeric_value, unit_of_measure, result_status, recorded_at
FROM hospital_patient_labs
WHERE sync_status = 'NEW';

db:update.db:sql:
UPDATE hospital_patient_labs
SET sync_status = 'PROCESSED'
WHERE lab_id = :labId;

